from itertools import combinations


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    initial_mask = bit.get(source, 0)
    budget = data["coupons"]
    deadline = data["deadline"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    initial = (source, 0, initial_mask)
    best = {initial: start}
    queue = [(start, source, 0, initial_mask)]
    while queue:
        time, node, used, mask = heapq.heappop(queue)
        state = (node, used, mask)
        if best.get(state) != time:
            continue
        if (node == target and mask == full and
                (coupon_rule == "at_most" or used == budget)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < budget:
                discount = edge.get("discount", 0)
                options.append((max(minimum_duration, edge["duration"] - discount), used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > deadline:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_used, next_mask)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_used, next_mask))
    return {"arrival": None}


def _build_route(coupon_rule, minimum_duration):
    return lambda data: _route(data, coupon_rule, minimum_duration)


def _build_ledger():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            amount = net + tax
            if event.get("kind") == "refund":
                amount = -amount
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + amount
        return {"balances": balances}
    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        roots = data["roots"]
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows_by_name = {}
        for name in names:
            rows_by_name[name] = {row["version"]: row for row in packages[name]}

        choices = []
        for name in names:
            choices.append([-1] + sorted(rows_by_name[name]))

        best_vector = None
        best_versions = None
        for vector in __import__("itertools").product(*choices):
            installed = {name: version for name, version in zip(names, vector) if version != -1}
            valid = True
            for name, bounds in roots.items():
                version = installed.get(name)
                if version is None or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, version in installed.items():
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
            if not valid:
                continue

            graph = {name: [] for name in installed}
            for name, version in installed.items():
                row = rows_by_name[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = installed.get(other)
                    if other_version is None or not dep["min"] <= other_version <= dep["max"]:
                        valid = False
                        break
                    graph[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in graph[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True
            if not all(visit(name) for name in graph):
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(graph[name])
            if reachable != set(installed):
                continue
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_versions = installed

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_jobs():
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        if not mandatory.issubset({job["id"] for job in jobs}) or len(mandatory) > k:
            return {"error": "impossible"}
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


